CREATE DATABASE IF NOT EXISTS project_hub_pro_db;
USE project_hub_pro_db;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(64) NOT NULL,role VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,description TEXT,deadline DATE,manager_id INT,status VARCHAR(30) DEFAULT 'Planning',FOREIGN KEY(manager_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS tasks(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,title VARCHAR(150) NOT NULL,assignee_id INT,status VARCHAR(30) DEFAULT 'To Do',FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(assignee_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS settings(setting_key VARCHAR(60) PRIMARY KEY,setting_value VARCHAR(255));
INSERT INTO settings VALUES('site_name','Project Hub') ON DUPLICATE KEY UPDATE setting_value=setting_value;
